     9→import Foundation
    10→
    11→enum VoiceMessageMediaManagerError: Error {
    12→    case unsupportedMimeTye
    13→    case missingURL
    14→}
    15→
    16→private final class VoiceMessageConversionRequest {
    17→    var continuations: [CheckedContinuation<URL, Error>] = []
    18→}
    19→
    20→class VoiceMessageMediaManager: VoiceMessageMediaManagerProtocol {
    21→    private let mediaProvider: MediaProviderProtocol
    22→    private let voiceMessageCache: VoiceMessageCacheProtocol
    23→    private let audioConverter: AudioConverterProtocol
    24→    
    25→    private let processingQueue: DispatchQueue
    26→    private var conversionRequests = [MediaSourceProxy: VoiceMessageConversionRequest]()
    27→    
    28→    private let supportedVoiceMessageMimeType = "audio/ogg"
    29→    
    30→    init(mediaProvider: MediaProviderProtocol,
    31→         voiceMessageCache: VoiceMessageCacheProtocol = VoiceMessageCache(),
    32→         audioConverter: AudioConverterProtocol = AudioConverter(),
    33→         processingQueue: DispatchQueue = .global()) {
    34→        self.mediaProvider = mediaProvider
    35→        self.voiceMessageCache = voiceMessageCache
    36→        self.audioConverter = audioConverter
    37→        self.processingQueue = processingQueue
    38→    }
    39→
    40→    deinit {
    41→        voiceMessageCache.clearCache()
    42→    }
    43→    
    44→    func loadVoiceMessageFromSource(_ source: MediaSourceProxy, body: String?) async throws -> URL {
    45→        guard let mimeType = source.mimeType, mimeType.starts(with: supportedVoiceMessageMimeType) else {
    46→            throw VoiceMessageMediaManagerError.unsupportedMimeTye
    47→        }
    48→        
    49→        // Do we already have a converted version?
    50→        if let fileURL = voiceMessageCache.fileURL(for: source) {
    51→            return fileURL
    52→        }
    53→                
    54→        // Otherwise, load the file from source
    55→        guard case .success(let fileHandle) = await mediaProvider.loadFileFromSource(source, filename: body) else {
    56→            throw MediaProviderError.failedRetrievingFile
    57→        }
    58→        
    59→        return try await enqueueVoiceMessageConversionRequest(forSource: source) { [audioConverter, voiceMessageCache] in
    60→            // Do we already have a converted version?
    61→            if let fileURL = voiceMessageCache.fileURL(for: source) {
    62→                return fileURL
    63→            }
    64→
    65→            // Convert from ogg
    66→            guard let url = fileHandle.url else {
    67→                throw VoiceMessageMediaManagerError.missingURL
    68→            }
    69→            let convertedFileURL = URL.temporaryDirectory.appendingPathComponent(url.deletingPathExtension().lastPathComponent).appendingPathExtension(AudioConverterPreferredFileExtension.mpeg4aac.rawValue)
    70→            try audioConverter.convertToMPEG4AAC(sourceURL: url, destinationURL: convertedFileURL)
    71→
    72→            // Cache the file and return the url
    73→            let result = voiceMessageCache.cache(mediaSource: source, using: convertedFileURL, move: true)
    74→            switch result {
    75→            case .success(let url):
    76→                return url
    77→            case .failure(let error):
    78→                throw error
    79→            }
    80→        }
    81→    }
    82→    
    83→    // MARK: - Private
    84→    
    85→    private func enqueueVoiceMessageConversionRequest(forSource source: MediaSourceProxy, operation: @escaping () throws -> URL) async throws -> URL {
    86→        if let conversionRequests = conversionRequests[source] {
    87→            return try await withCheckedThrowingContinuation { continuation in
    88→                conversionRequests.continuations.append(continuation)
    89→            }
    90→        }
    91→        
    92→        let conversionRequest = VoiceMessageConversionRequest()
    93→        conversionRequests[source] = conversionRequest
    94→        
    95→        defer {
    96→            conversionRequests[source] = nil
    97→        }
    98→        
    99→        do {
   100→            let result = try await Task.dispatch(on: processingQueue) {
   101→                try operation()
   102→            }
   103→            
   104→            conversionRequest.continuations.forEach { $0.resume(returning: result) }
   105→            
   106→            return result
   107→            
   108→        } catch {
   109→            conversionRequest.continuations.forEach { $0.resume(throwing: error) }
   110→            throw error
   111→        }
   112→    }
   113→}
