     9→import AVFoundation
    10→import Combine
    11→import Foundation
    12→import UIKit
    13→
    14→private enum InternalAudioPlayerState {
    15→    case none
    16→    case loading
    17→    case readyToPlay
    18→    case playing
    19→    case paused
    20→    case stopped
    21→    case finishedPlaying
    22→    case error(Error)
    23→}
    24→
    25→class AudioPlayer: NSObject, AudioPlayerProtocol {
    26→    var sourceURL: URL?
    27→    
    28→    private var playerItem: AVPlayerItem?
    29→    private var internalAudioPlayer: AVQueuePlayer?
    30→    
    31→    private var cancellables = Set<AnyCancellable>()
    32→    private let actionsSubject: PassthroughSubject<AudioPlayerAction, Never> = .init()
    33→    var actions: AnyPublisher<AudioPlayerAction, Never> {
    34→        actionsSubject.eraseToAnyPublisher()
    35→    }
    36→    
    37→    private var internalState = InternalAudioPlayerState.none
    38→    
    39→    private var statusObserver: NSKeyValueObservation?
    40→    private var rateObserver: NSKeyValueObservation?
    41→    private var autoplay = false
    42→    
    43→    private let audioSession = AVAudioSession.sharedInstance()
    44→    
    45→    // periphery:ignore - when set to nil is automatically cancelled
    46→    @CancellableTask private var releaseAudioSessionTask: Task<Void, Never>?
    47→    
    48→    private let releaseAudioSessionTimeoutInterval = 5.0
    49→    
    50→    private(set) var playbackURL: URL?
    51→    
    52→    private var deinitInProgress = false
    53→    
    54→    var duration: TimeInterval {
    55→        abs(CMTimeGetSeconds(internalAudioPlayer?.currentItem?.duration ?? .zero))
    56→    }
    57→    
    58→    var currentTime: TimeInterval {
    59→        let currentTime = abs(CMTimeGetSeconds(internalAudioPlayer?.currentTime() ?? .zero))
    60→        return currentTime.isFinite ? currentTime : .zero
    61→    }
    62→    
    63→    var state: MediaPlayerState {
    64→        if case .loading = internalState {
    65→            return .loading
    66→        }
    67→        if case .stopped = internalState {
    68→            return .stopped
    69→        }
    70→        if case .playing = internalState {
    71→            return .playing
    72→        }
    73→        if case .paused = internalState {
    74→            return .paused
    75→        }
    76→        if case .error = internalState {
    77→            return .error
    78→        }
    79→        return .stopped
    80→    }
    81→    
    82→    private var isStopped = true
    83→    
    84→    deinit {
    85→        deinitInProgress = true
    86→        stop()
    87→        unloadContent()
    88→    }
    89→    
    90→    func load(sourceURL: URL, playbackURL: URL, autoplay: Bool) {
    91→        unloadContent()
    92→        setInternalState(.loading)
    93→        self.sourceURL = sourceURL
    94→        self.playbackURL = playbackURL
    95→        self.autoplay = autoplay
    96→        playerItem = AVPlayerItem(url: playbackURL)
    97→        internalAudioPlayer = AVQueuePlayer(playerItem: playerItem)
    98→        addObservers()
    99→    }
   100→    
   101→    func reset() {
   102→        stop()
   103→        unloadContent()
   104→    }
   105→    
   106→    func play() {
   107→        isStopped = false
   108→        setupAudioSession()
   109→        internalAudioPlayer?.play()
   110→    }
   111→    
   112→    func pause() {
   113→        guard case .playing = internalState else { return }
   114→        internalAudioPlayer?.pause()
   115→        releaseAudioSession(after: releaseAudioSessionTimeoutInterval)
   116→    }
   117→    
   118→    func stop() {
   119→        guard !isStopped else { return }
   120→        isStopped = true
   121→        internalAudioPlayer?.pause()
   122→        internalAudioPlayer?.seek(to: .zero)
   123→        releaseAudioSession(after: releaseAudioSessionTimeoutInterval)
   124→    }
   125→    
   126→    func seek(to progress: Double) async {
   127→        guard let internalAudioPlayer else { return }
   128→        let time = progress * duration
   129→        await internalAudioPlayer.seek(to: CMTime(seconds: time, preferredTimescale: 60))
   130→    }
   131→    
   132→    // MARK: - Private
   133→    
   134→    private func setupAudioSession() {
   135→        releaseAudioSessionTask = nil
   136→        do {
   137→            try audioSession.setCategory(.playback)
   138→            try audioSession.setActive(true)
   139→        } catch {
   140→            MXLog.error("Could not redirect audio playback to speakers.")
   141→        }
   142→    }
   143→    
   144→    private func releaseAudioSession(after timeInterval: TimeInterval) {
   145→        guard !deinitInProgress else {
   146→            releaseAudioSession()
   147→            return
   148→        }
   149→        releaseAudioSessionTask = Task { [weak self] in
   150→            try? await Task.sleep(for: .seconds(timeInterval))
   151→            guard !Task.isCancelled else { return }
   152→            
   153→            self?.releaseAudioSession()
   154→        }
   155→    }
   156→    
   157→    private func releaseAudioSession() {
   158→        releaseAudioSessionTask = nil
   159→        if audioSession.category == .playback, !audioSession.isOtherAudioPlaying {
   160→            MXLog.info("releasing audio session")
   161→            try? audioSession.setActive(false, options: .notifyOthersOnDeactivation)
   162→        }
   163→    }
   164→    
   165→    private func unloadContent() {
   166→        sourceURL = nil
   167→        playbackURL = nil
   168→        internalAudioPlayer?.replaceCurrentItem(with: nil)
   169→        internalAudioPlayer = nil
   170→        playerItem = nil
   171→        removeObservers()
   172→    }
   173→
   174→    private func addObservers() {
   175→        guard let internalAudioPlayer, let playerItem else {
   176→            return
   177→        }
   178→        
   179→        statusObserver = playerItem.observe(\.status, options: [.old, .new]) { [weak self] _, _ in
   180→            guard let self else { return }
   181→            
   182→            switch playerItem.status {
   183→            case .failed:
   184→                setInternalState(.error(playerItem.error ?? AudioPlayerError.genericError))
   185→            case .readyToPlay:
   186→                guard state == .loading else { return }
   187→                setInternalState(.readyToPlay)
   188→            default:
   189→                break
   190→            }
   191→        }
   192→                
   193→        rateObserver = internalAudioPlayer.observe(\.rate, options: [.old, .new]) { [weak self] _, _ in
   194→            guard let self else { return }
   195→            
   196→            if internalAudioPlayer.rate == 0 {
   197→                if isStopped {
   198→                    setInternalState(.stopped)
   199→                } else {
   200→                    setInternalState(.paused)
   201→                }
   202→            } else {
   203→                setInternalState(.playing)
   204→            }
   205→        }
   206→                
   207→        NotificationCenter.default.publisher(for: Notification.Name.AVPlayerItemDidPlayToEndTime)
   208→            .sink { [weak self] _ in
   209→                guard let self else { return }
   210→                setInternalState(.finishedPlaying)
   211→            }
   212→            .store(in: &cancellables)
   213→    }
   214→    
   215→    private func removeObservers() {
   216→        statusObserver?.invalidate()
   217→        rateObserver?.invalidate()
   218→        cancellables.removeAll()
   219→    }
   220→    
   221→    private func setInternalState(_ state: InternalAudioPlayerState) {
   222→        internalState = state
   223→        switch state {
   224→        case .none:
   225→            break
   226→        case .loading:
   227→            actionsSubject.send(.didStartLoading)
   228→        case .readyToPlay:
   229→            actionsSubject.send(.didFinishLoading)
   230→            if autoplay {
   231→                autoplay = false
   232→                play()
   233→            }
   234→        case .playing:
   235→            actionsSubject.send(.didStartPlaying)
   236→        case .paused:
   237→            actionsSubject.send(.didPausePlaying)
   238→        case .stopped:
   239→            actionsSubject.send(.didStopPlaying)
   240→        case .finishedPlaying:
   241→            actionsSubject.send(.didFinishPlaying)
   242→            unloadContent()
   243→        case .error(let error):
   244→            MXLog.error("audio player did fail. \(error)")
   245→            actionsSubject.send(.didFailWithError(error: error))
   246→        }
   247→    }
   248→}
