     9→import Combine
    10→import Foundation
    11→import MediaPlayer
    12→import UIKit
    13→
    14→enum AudioPlayerPlaybackState {
    15→    case loading
    16→    case readyToPlay
    17→    case playing
    18→    case stopped
    19→    case error
    20→}
    21→
    22→enum AudioPlayerStateIdentifier {
    23→    case timelineItemIdentifier(TimelineItemIdentifier)
    24→    case recorderPreview
    25→}
    26→
    27→@MainActor
    28→class AudioPlayerState: ObservableObject, Identifiable {
    29→    let id: AudioPlayerStateIdentifier
    30→    let title: String
    31→    private(set) var duration: Double
    32→    let waveform: EstimatedWaveform
    33→    @Published private(set) var progress: Double
    34→    
    35→    @Published private(set) var playbackState: AudioPlayerPlaybackState
    36→    /// It's similar to `playbackState`, with the a difference: `.loading`
    37→    /// updates are delayed by a fixed amount of time
    38→    @Published private(set) var playerButtonPlaybackState: AudioPlayerPlaybackState
    39→
    40→    private weak var audioPlayer: AudioPlayerProtocol?
    41→    private var audioPlayerSubscription: AnyCancellable?
    42→    private var playbackStateSubscription: AnyCancellable?
    43→    private var displayLink: CADisplayLink?
    44→
    45→    /// The file url that the last player attached to this object has loaded.
    46→    /// The file url persists even if the AudioPlayer will be detached later.
    47→    private(set) var fileURL: URL?
    48→    
    49→    var showProgressIndicator: Bool {
    50→        progress > 0
    51→    }
    52→
    53→    var isAttached: Bool {
    54→        audioPlayer != nil
    55→    }
    56→    
    57→    var isPublishingProgress: Bool {
    58→        displayLink != nil
    59→    }
    60→
    61→    init(id: AudioPlayerStateIdentifier, title: String, duration: Double, waveform: EstimatedWaveform? = nil, progress: Double = 0.0) {
    62→        self.id = id
    63→        self.title = title
    64→        self.duration = duration
    65→        self.waveform = waveform ?? EstimatedWaveform(data: [])
    66→        self.progress = progress
    67→        playbackState = .stopped
    68→        playerButtonPlaybackState = .stopped
    69→        setupPlaybackStateSubscription()
    70→    }
    71→    
    72→    deinit {
    73→        displayLink?.invalidate()
    74→        displayLink = nil
    75→    }
    76→    
    77→    func updateState(progress: Double) async {
    78→        let progress = max(0.0, min(progress, 1.0))
    79→        self.progress = progress
    80→        if let audioPlayer {
    81→            var shouldResumeProgressPublishing = false
    82→            if audioPlayer.state == .playing {
    83→                shouldResumeProgressPublishing = true
    84→                stopPublishProgress()
    85→            }
    86→            await audioPlayer.seek(to: progress)
    87→            if shouldResumeProgressPublishing, audioPlayer.state == .playing {
    88→                startPublishProgress()
    89→            }
    90→        }
    91→    }
    92→    
    93→    func attachAudioPlayer(_ audioPlayer: AudioPlayerProtocol) {
    94→        if self.audioPlayer != nil {
    95→            detachAudioPlayer()
    96→        }
    97→        playbackState = .loading
    98→        self.audioPlayer = audioPlayer
    99→        subscribeToAudioPlayer(audioPlayer: audioPlayer)
   100→    }
   101→    
   102→    func detachAudioPlayer() {
   103→        audioPlayer?.stop()
   104→        stopPublishProgress()
   105→        audioPlayerSubscription = nil
   106→        audioPlayer = nil
   107→        playbackState = .stopped
   108→    }
   109→    
   110→    func reportError() {
   111→        playbackState = .error
   112→    }
   113→    
   114→    // MARK: - Private
   115→    
   116→    private func subscribeToAudioPlayer(audioPlayer: AudioPlayerProtocol) {
   117→        audioPlayerSubscription = audioPlayer.actions
   118→            .receive(on: DispatchQueue.main)
   119→            .sink { [weak self] action in
   120→                guard let self else {
   121→                    return
   122→                }
   123→                Task {
   124→                    await self.handleAudioPlayerAction(action)
   125→                }
   126→            }
   127→    }
   128→    
   129→    private func handleAudioPlayerAction(_ action: AudioPlayerAction) async {
   130→        switch action {
   131→        case .didStartLoading:
   132→            playbackState = .loading
   133→        case .didFinishLoading:
   134→            if let audioPlayerDuration = audioPlayer?.duration, audioPlayerDuration != duration {
   135→                MXLog.info("updating duration: \(duration) -> \(audioPlayerDuration)")
   136→                duration = audioPlayerDuration
   137→            }
   138→            fileURL = audioPlayer?.playbackURL
   139→            playbackState = .readyToPlay
   140→        case .didStartPlaying:
   141→            if let audioPlayer {
   142→                await restoreAudioPlayerState(audioPlayer: audioPlayer)
   143→            }
   144→            startPublishProgress()
   145→            playbackState = .playing
   146→            setUpRemoteCommandCenter()
   147→        case .didPausePlaying:
   148→            stopPublishProgress()
   149→            playbackState = .stopped
   150→        case .didStopPlaying:
   151→            playbackState = .stopped
   152→            stopPublishProgress()
   153→            tearDownRemoteCommandCenter()
   154→        case .didFinishPlaying:
   155→            playbackState = .stopped
   156→            progress = 0.0
   157→            stopPublishProgress()
   158→            tearDownRemoteCommandCenter()
   159→        case .didFailWithError:
   160→            stopPublishProgress()
   161→            playbackState = .error
   162→        }
   163→    }
   164→    
   165→    private func startPublishProgress() {
   166→        if displayLink != nil {
   167→            stopPublishProgress()
   168→        }
   169→        displayLink = CADisplayLink(target: self, selector: #selector(updateProgress))
   170→        displayLink?.preferredFrameRateRange = .init(minimum: 10, maximum: 20)
   171→        displayLink?.add(to: .current, forMode: .common)
   172→    }
   173→    
   174→    // periphery:ignore:parameters displayLink - required for objc selector
   175→    @objc private func updateProgress(displayLink: CADisplayLink) {
   176→        if let currentTime = audioPlayer?.currentTime, duration > 0 {
   177→            progress = currentTime / duration
   178→        }
   179→        
   180→        updateNowPlayingInfoCenter()
   181→    }
   182→    
   183→    private func stopPublishProgress() {
   184→        displayLink?.invalidate()
   185→        displayLink = nil
   186→    }
   187→    
   188→    private func restoreAudioPlayerState(audioPlayer: AudioPlayerProtocol) async {
   189→        await audioPlayer.seek(to: progress)
   190→    }
   191→    
   192→    private func setupPlaybackStateSubscription() {
   193→        playbackStateSubscription = $playbackState
   194→            .map { state in
   195→                switch state {
   196→                case .loading:
   197→                    return Just(state)
   198→                        .delay(for: .seconds(2), scheduler: RunLoop.main)
   199→                        .eraseToAnyPublisher()
   200→                case .playing, .stopped, .error, .readyToPlay:
   201→                    return Just(state)
   202→                        .eraseToAnyPublisher()
   203→                }
   204→            }
   205→            .switchToLatest()
   206→            .removeDuplicates()
   207→            .weakAssign(to: \.playerButtonPlaybackState, on: self)
   208→    }
   209→    
   210→    private func setUpRemoteCommandCenter() {
   211→        UIApplication.shared.beginReceivingRemoteControlEvents()
   212→        
   213→        let commandCenter = MPRemoteCommandCenter.shared()
   214→        
   215→        commandCenter.playCommand.isEnabled = true
   216→        commandCenter.playCommand.removeTarget(nil)
   217→        commandCenter.playCommand.addTarget { [weak self] _ in
   218→            guard let audioPlayer = self?.audioPlayer else {
   219→                return MPRemoteCommandHandlerStatus.commandFailed
   220→            }
   221→            
   222→            audioPlayer.play()
   223→            
   224→            return MPRemoteCommandHandlerStatus.success
   225→        }
   226→        
   227→        commandCenter.pauseCommand.isEnabled = true
   228→        commandCenter.pauseCommand.removeTarget(nil)
   229→        commandCenter.pauseCommand.addTarget { [weak self] _ in
   230→            guard let audioPlayer = self?.audioPlayer else {
   231→                return MPRemoteCommandHandlerStatus.commandFailed
   232→            }
   233→            
   234→            audioPlayer.pause()
   235→
   236→            return MPRemoteCommandHandlerStatus.success
   237→        }
   238→        
   239→        commandCenter.skipForwardCommand.isEnabled = true
   240→        commandCenter.skipForwardCommand.removeTarget(nil)
   241→        commandCenter.skipForwardCommand.addTarget { [weak self] event in
   242→            guard let audioPlayer = self?.audioPlayer, let skipEvent = event as? MPSkipIntervalCommandEvent else {
   243→                return MPRemoteCommandHandlerStatus.commandFailed
   244→            }
   245→            
   246→            Task {
   247→                await audioPlayer.seek(to: audioPlayer.currentTime + skipEvent.interval)
   248→            }
   249→            
   250→            return MPRemoteCommandHandlerStatus.success
   251→        }
   252→        
   253→        commandCenter.skipBackwardCommand.isEnabled = true
   254→        commandCenter.skipBackwardCommand.removeTarget(nil)
   255→        commandCenter.skipBackwardCommand.addTarget { [weak self] event in
   256→            guard let audioPlayer = self?.audioPlayer, let skipEvent = event as? MPSkipIntervalCommandEvent else {
   257→                return MPRemoteCommandHandlerStatus.commandFailed
   258→            }
   259→            
   260→            Task {
   261→                await audioPlayer.seek(to: audioPlayer.currentTime - skipEvent.interval)
   262→            }
   263→            
   264→            return MPRemoteCommandHandlerStatus.success
   265→        }
   266→    }
   267→    
   268→    private func tearDownRemoteCommandCenter() {
   269→        UIApplication.shared.endReceivingRemoteControlEvents()
   270→        
   271→        let nowPlayingInfoCenter = MPNowPlayingInfoCenter.default()
   272→        nowPlayingInfoCenter.nowPlayingInfo = nil
   273→        nowPlayingInfoCenter.playbackState = .stopped
   274→        
   275→        let commandCenter = MPRemoteCommandCenter.shared()
   276→        commandCenter.playCommand.isEnabled = false
   277→        commandCenter.playCommand.removeTarget(nil)
   278→        commandCenter.pauseCommand.isEnabled = false
   279→        commandCenter.pauseCommand.removeTarget(nil)
   280→        commandCenter.skipForwardCommand.isEnabled = false
   281→        commandCenter.skipForwardCommand.removeTarget(nil)
   282→        commandCenter.skipBackwardCommand.isEnabled = false
   283→        commandCenter.skipBackwardCommand.removeTarget(nil)
   284→    }
   285→    
   286→    private func updateNowPlayingInfoCenter() {
   287→        guard let audioPlayer else {
   288→            return
   289→        }
   290→        
   291→        let nowPlayingInfoCenter = MPNowPlayingInfoCenter.default()
   292→        nowPlayingInfoCenter.nowPlayingInfo = [MPMediaItemPropertyTitle: title,
   293→                                               MPMediaItemPropertyPlaybackDuration: audioPlayer.duration as Any,
   294→                                               MPNowPlayingInfoPropertyElapsedPlaybackTime: audioPlayer.currentTime as Any]
   295→    }
