    11→struct EstimatedWaveform: Equatable, Hashable {
    12→    static let dataRange: ClosedRange<UInt16> = 0...1024
    13→    let data: [UInt16]
    14→}
    15→
    16→extension EstimatedWaveform {
    17→    /// Maps the `data` array to Float values in the range 0...1 respecting the `Self.dataRange` limits.
    18→    /// Up to `maxSamplesCount` will be returned in the output array
    19→    func normalisedData(maxSamplesCount: Int) -> [Float] {
    20→        guard maxSamplesCount > 0 else {
    21→            return []
    22→        }
    23→
    24→        // Filter the data to keep only the expected number of samples
    25→        let result: [UInt16]
    26→        if data.count > maxSamplesCount {
    27→            result = (0..<maxSamplesCount)
    28→                .map { index in
    29→                    let targetIndex = Int((Double(index) * (Double(data.count) / Double(maxSamplesCount))).rounded())
    30→                    return UInt16(data[targetIndex])
    31→                }
    32→        } else {
    33→            result = data
    34→        }
    35→
    36→        // Normalize the sample in the allowed range
    37→        return result.map { Float($0) / Float(Self.dataRange.upperBound) }
    38→    }
    39→}
