    71→        let count = Int(size.width / (lineWidth + linePadding))
    72→        // Rebuild the normalized waveform data only if the count has changed
    73→        if normalizedWaveformData.count == count {
    74→            return
    75→        }
    76→        normalizedWaveformData = waveform.normalisedData(maxSamplesCount: count)
