    87→private struct WaveformShape: Shape {
    88→    let lineWidth: CGFloat
    89→    let linePadding: CGFloat
    90→    let waveformData: [Float]
    91→    var minimumGraphAmplitude: CGFloat = 1.0
    92→    
    93→    func path(in rect: CGRect) -> Path {
    94→        let width = rect.size.width
    95→        let height = rect.size.height
    96→        let centerY = rect.size.height / 2
    97→        var xOffset: CGFloat = lineWidth / 2
    98→        var index = 0
    99→        
   100→        var path = Path()
   101→        while xOffset <= width {
   102→            let sample = CGFloat(index >= waveformData.count ? 0 : waveformData[index])
   103→            let drawingAmplitude = max(minimumGraphAmplitude, sample * (height - 2))
   104→            
   105→            path.move(to: CGPoint(x: xOffset, y: centerY - drawingAmplitude / 2))
   106→            path.addLine(to: CGPoint(x: xOffset, y: centerY + drawingAmplitude / 2))
   107→            xOffset += lineWidth + linePadding
   108→            index += 1
   109→        }
   110→        
   111→        return path
   112→    }
   113→}
